function Badge({ children, tone = "green" }: { children: React.ReactNode; tone?: "green" | "blue" | "orange" | "gray" }) {
  return <span className={`badge ${tone}`}>{children}</span>;
}

function Action({ children, onClick, secondary = false, danger = false }: { children: React.ReactNode; onClick?: () => void; secondary?: boolean; danger?: boolean }) {
  return <button className={`action ${secondary ? "secondary" : ""} ${danger ? "danger" : ""}`} onClick={onClick}>{children}</button>;
}

function Card({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  return <section className={`card ${className}`}>{children}</section>;
}

function Row({ icon, title, value, green = false }: { icon?: string; title: string; value?: string; green?: boolean }) {
  return <div className="row"><span className="row-icon">{icon ?? "•"}</span><span className="row-title">{title}</span>{value && <strong className={green ? "success" : ""}>{value}</strong>}<span className="chev">›</span></div>;
}

function Product({ kind = "tv", title = "Samsung QE65Q80D, 65″", price }: { kind?: "tv" | "pods" | "robot"; title?: string; price?: string }) {
  const icons = { tv: "📺", pods: "🎧", robot: "◉" };
  return <div className="product"><div className={`product-art ${kind}`}>{icons[kind]}</div><div><strong>{title}</strong>{price && <div className="product-price">{price}</div>}</div></div>;
}

function ProgressSteps({ active = 2 }: { active?: number }) {
  const steps = ["Сравниваю характеристики", "Проверяю 47 моделей", "Получаю предложения магазинов", "Проверяю продавцов"];
  return <div className="steps">{steps.map((step, i) => <div className={`step ${i < active ? "done" : i === active ? "active" : ""}`} key={step}><span>{i < active ? "✓" : i + 1}</span><div>{step}</div></div>)}</div>;
}

function MobileShell({ role, title, children, activeTab, onBack }: { role: Role; title?: string; children: React.ReactNode; activeTab?: string; onBack?: () => void }) {
  const tabs = role === "seller" ? [["Спрос", "◎"], ["Сделки", "♧"], ["Товары", "▢"], ["Профиль", "○"]] : [["Агент", "✦"], ["Сделки", "♧"], ["Покупки", "▢"], ["Профиль", "○"]];
  return <div className="phone"><div className="phone-top"><b>9:41</b><span>▮▮▮ ◉ ▰</span></div>{title && <header className="mobile-header"><button onClick={onBack} aria-label="Назад">‹</button><h2>{title}</h2><span>•••</span></header>}<div className="mobile-body">{children}</div><nav className="bottom-nav">{tabs.map(([label, icon]) => <div className={activeTab === label ? "selected" : ""} key={label}><span>{icon}</span><small>{label}</small></div>)}</nav><div className="home-indicator" /></div>;
}

