  if (id === "request") return <MobileShell role="seller" title="Запрос покупателя" activeTab="Спрос"><Card className="center"><p className="link">◷ Ответить до 09:36</p></Card><Product /><Badge>Совпадение 99%</Badge><Card><Row icon="⌖" title="Москва" /><Row icon="▤" title="Доставка до пятницы" /><Row icon="▣" title="Новый товар" /><Row icon="♢" title="Гарантия от 1 года" /></Card><Card><p className="muted">Лучшая цена маркетплейсов</p><h2>86 900 ₽</h2></Card><Card className="saving-card"><p>Чтобы стать первым</p><h1>85 900 ₽</h1><b>или лучше</b></Card><p className="safe-note">6 магазинов приглашено · 3 ответили</p><Action onClick={() => go("bid")}>Сделать предложение</Action></MobileShell>;
  if (id === "bid") return <MobileShell role="seller" title="Предложение" activeTab="Спрос"><Product /><Badge>Совпадение 99%</Badge><h3>Ваша цена</h3><input className="field price-input" value="85 900 ₽" readOnly /><p className="success">На 1 000 ₽ выгоднее маркетплейсов</p><h3>Доставка</h3><Card><label className="radio"><input type="radio" defaultChecked name="delivery" /> Курьер магазина · завтра</label><label className="radio"><input type="radio" name="delivery" /> СДЭК · 1–2 дня</label><label className="radio"><input type="radio" name="delivery" /> Самовывоз · сегодня</label></Card><Card><div className="price-line"><span>Покупатель платит</span><b>85 900 ₽</b></div><div className="price-line"><span>Комиссия 2%</span><b>−1 718 ₽</b></div><div className="price-line total success"><span>Вы получите</span><b>84 182 ₽</b></div></Card><Action onClick={() => go("seller-deal")}>Отправить предложение</Action></MobileShell>;
  if (id === "seller-deal") return <MobileShell role="seller" title="Сделка №1842" activeTab="Сделки"><Badge>Покупатель оплатил</Badge><Card className="safe-card center"><div className="shield">✓</div><h1>85 900 ₽ зарезервированы</h1><p>Деньги поступят после получения товара</p></Card><OrderSteps /><Card><b>Курьер магазина · завтра, 12:00–16:00</b><Action secondary>Указать трек-номер</Action></Card><p className="safe-note">♢ Спор и возврат защищены сервисом</p><Action onClick={() => go("inventory")}>Товар передан в доставку</Action></MobileShell>;
  if (id === "inventory") return <MobileShell role="seller" activeTab="Товары"><h1>Товары</h1><input className="field" placeholder="Название или штрих-код" /><Action secondary>＋ Добавить товар</Action><div className="mini-stats"><span><b>124</b>В наличии</span><span className="orange-text"><b>8</b>Заканчиваются</span><span><b>3</b>Скрыты</span></div><Stock kind="tv" title="Samsung QE65Q80D, 65″" note="3 шт. · 85 900 ₽" badge="Активен" /><Stock kind="robot" title="Roborock Q8 Max" note="1 шт. · 36 500 ₽" badge="Заканчивается" orange /><Stock kind="pods" title="AirPods Pro 2" note="0 шт." badge="Нет в наличии" /><Action onClick={() => go("analytics")}>Посмотреть результаты</Action></MobileShell>;
  if (id === "analytics") return <MobileShell role="seller" activeTab="Профиль"><div className="title-row"><h1>Результаты</h1><Badge tone="blue">30 дней</Badge></div><div className="stat-grid"><Stat label="Продажи" value="42" /><Stat label="Выручка" value="1 842 300 ₽" /><Stat label="Комиссия" value="36 846 ₽" /><Stat label="Конверсия" value="18%" /></div><Card><h3>Выручка</h3><div className="chart"><i /><i /><i /><i /><i /><i /><i /><i /></div></Card><Card><div className="title-row"><h3>♢ Надёжность</h3><b className="success">96/100</b></div><div className="price-line"><span>Отмены</span><b>1,2%</b></div><div className="price-line"><span>В срок</span><b>97%</b></div><div className="price-line"><span>Оценка</span><b>★ 4,9</b></div></Card><Card className="saving-card"><p>К выплате</p><h1>284 182 ₽</h1><Action>Вывести деньги</Action></Card></MobileShell>;
