function Stock({ kind, title, note, badge, orange }: { kind: "tv" | "robot" | "pods"; title: string; note: string; badge: string; orange?: boolean }) { return <Card className="stock"><Product kind={kind} title={title} /><p>{note}</p><Badge tone={orange ? "orange" : badge === "Активен" ? "green" : "gray"}>{badge}</Badge><span className="toggle">●</span></Card>; }
function Stat({ label, value }: { label: string; value: string }) { return <Card><small>{label}</small><h3>{value}</h3></Card>; }

