function AdminTitle({ title, action }: { title: string; action?: string }) { return <div className="admin-title"><div><p className="eyebrow">Управление сервисом</p><h1>{title}</h1></div>{action && <button>{action}</button>}</div>; }
function AdminStat({ label, value }: { label: string; value: string }) { return <Card><small>{label}</small><h2>{value}</h2><span className="success">+8,7% за 7 дней ↗</span></Card>; }
function LineChart() { return <div className="line-chart"><div className="grid-lines" /><svg viewBox="0 0 500 180" preserveAspectRatio="none"><polyline points="0,145 55,125 105,135 160,80 220,102 275,55 335,88 390,35 445,62 500,28" fill="none" stroke="#315cff" strokeWidth="5" /><polyline points="0,158 55,148 105,152 160,112 220,125 275,95 335,110 390,82 445,96 500,72" fill="none" stroke="#16a15f" strokeWidth="4" /></svg></div>; }
function Filters() { return <div className="filters"><button>Статус: Все⌄</button><button>Город: Все⌄</button><button>07.05.2026 — 14.05.2026</button><button>Ещё фильтры⌄</button></div>; }
function AdminTable({ headers, rows }: { headers: string[]; rows: string[][] }) {
  const columns = { gridTemplateColumns: `repeat(${headers.length}, minmax(70px, 1fr))` };
  return <div className="admin-table"><div className="thead" style={columns}>{headers.map(h => <b key={h}>{h}</b>)}</div>{rows.map((row, ri) => <div className="trow" style={columns} key={ri}>{row.map((v, i) => <span key={i} className={i === row.length - 1 ? "status-cell" : ""}>{v}</span>)}</div>)}</div>;
}

export function PrototypeExperience() {
  const [role, setRole] = useState<Role>("buyer");
  const [screenId, setScreenId] = useState("home");
  const screens = roleScreens[role];
  const index = screens.findIndex((s) => s.id === screenId);
  const currentIndex = index < 0 ? 0 : index;
  const current = screens[currentIndex];
  const groups = useMemo(() => Array.from(new Set(screens.map((s) => s.group))), [screens]);

  const changeRole = (next: Role) => {
    setRole(next);
    setScreenId(next === "buyer" ? "home" : roleScreens[next][0].id);
  };
  const go = (id: string) => setScreenId(id);
  const previous = () => setScreenId(screens[Math.max(0, currentIndex - 1)].id);
  const next = () => setScreenId(screens[Math.min(screens.length - 1, currentIndex + 1)].id);

  return <main className="prototype-page"><header className="prototype-header"><div className="prototype-brand"><span>✦</span><div><b>Агент покупок</b><small>40 экранов прототипа + рабочий backend</small></div></div><div className="role-switch">{(["buyer", "seller", "admin"] as Role[]).map((r) => <button className={r === role ? "active" : ""} key={r} onClick={() => changeRole(r)}>{roleLabels[r]}</button>)}</div><div className="prototype-header-links"><a href="/live-search">Живой поиск</a><a href="/backend">Интеграции</a></div></header><div className={`prototype-workspace ${role === "admin" ? "admin-mode" : ""}`}><aside className="screen-list"><p className="eyebrow">Страницы проекта</p>{groups.map((group) => <div key={group}><h4>{group}</h4>{screens.filter((s) => s.group === group).map((s) => <button key={s.id} onClick={() => go(s.id)} className={s.id === current.id ? "active" : ""}><span>{screens.indexOf(s) + 1}</span>{s.title}</button>)}</div>)}</aside><section className="stage"><div className="stage-toolbar"><button onClick={previous} disabled={currentIndex === 0}>← Назад</button><div><b>{current.title}</b><span>{currentIndex + 1} из {screens.length}</span></div><button onClick={next} disabled={currentIndex === screens.length - 1}>Дальше →</button></div>{role === "buyer" && <BuyerScreen id={current.id} go={go} />}{role === "seller" && <SellerScreen id={current.id} go={go} />}{role === "admin" && <AdminScreen id={current.id} go={go} />}</section><aside className="flow-panel"><p className="eyebrow">Карта сценария</p><h3>{role === "buyer" ? "Путь покупателя" : role === "seller" ? "Путь продавца" : "Контур управления"}</h3><p>{role === "buyer" ? "Поиск, честная цена, безопасная покупка, уведомления и помощь после получения." : role === "seller" ? "От входящего спроса до выплаты, поддержки магазина и повторных продаж." : "Контроль данных, денег, продавцов, рисков, коммуникаций и сотрудников."}</p><div className="flow-steps">{screens.map((s, i) => <button onClick={() => go(s.id)} className={s.id === current.id ? "active" : i < currentIndex ? "done" : ""} key={s.id}><span>{i < currentIndex ? "✓" : i + 1}</span><div><small>{s.group}</small><b>{s.title}</b></div></button>)}</div><div className="prototype-note"><b>Проверено на полноту</b><p>Во всех ролях есть основной сценарий, уведомления, поддержка, безопасность, история действий и понятный следующий шаг.</p></div></aside></div></main>;
}

